/**
 * Draft a new figure (Day 26+) in the house style.
 *
 * One research essay, then the six profile files, each generated by Claude
 * Opus 5.5 (or the tier you choose) against a cached reference prefix: the
 * framework, the profile template, and the complete Alexander set as the
 * exemplar of structure and voice. Output is marked as a machine draft; run
 * `nova-tutor review <slug>` and read it yourself before it teaches anyone.
 */
import Anthropic from "@anthropic-ai/sdk";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { readCorpusFile, REPO_ROOT } from "../corpus/index.js";
import type { AgeRange, EraGroup } from "../corpus/types.js";
import { addUsage, emptyUsage, estimateCost, FALLBACK_BETA, resolveModel, type Effort, type UsageTotals } from "../inference/models.js";

export interface GenerateOptions {
  slug: string;
  name: string;
  eraGroup: EraGroup;
  day: number;
  /** Free-text era line, e.g. "Modern / Victorian Britain". */
  era?: string;
  domain?: string;
  /** Anything the author wants emphasized, avoided, or sourced. */
  notes?: string;
  /** Model tier or id; default tutor (Claude Opus 5.5). */
  model?: string;
  effort?: Effort;
  /** Let the model search the web while writing the research essay (Opus/Sonnet tiers only). */
  web?: boolean;
  /** Generate but do not write files. */
  dryRun?: boolean;
  /** Which existing figure to use as the structural exemplar. */
  exemplar?: string;
  root?: string;
  client?: Anthropic;
  onText?: (delta: string) => void;
  onStage?: (stage: string) => void;
}

export interface GenerateResult {
  files: string[];
  drafts: Record<string, string>;
  usage: UsageTotals;
  estimatedCostUsd: number;
}

const PROFILE_FILES: Array<{ file: string; brief: string }> = [
  { file: "README.md", brief: "the profile overview: title and subtitle, Born/Died/Era/Domain lines, The One-Minute Story, Why He Matters for Your Child (\"X teaches:\" and \"But also warns against:\" bullets), Formation Signature (Virtues, Risks, How He Was Formed), Student Lessons links, Teaching Resources links, Quick Practice Ideas by age" },
  { file: "student-ages-8-10.md", brief: "the student lesson for ages 8-10: a story told plainly for a young child, short sections, concrete virtues, discussion questions, things to do this week, a memory sentence" },
  { file: "student-ages-11-14.md", brief: "the student lesson for ages 11-14: the essential question, the deeper story with the formation made explicit, discussion questions, practices" },
  { file: "student-ages-15-18.md", brief: "the student lesson for ages 15-18: the central problem, primary sources, competing interpretations, comparative seminar, essay prompts" },
  { file: "parent-guide.md", brief: "the parent teaching guide: what the profile teaches, age-appropriate emphases (what to teach, what to leave for later), common misconceptions, sensitive topics, facilitation tips, what success looks like" },
  { file: "one-week-lesson.md", brief: "the five-day lesson plan: overview, materials, Monday through Friday sessions with timings, a hands-on project, assessment, optional extensions" },
];

const SYSTEM_INTRO = `You write educational biography for Nova Schola, a classical-formation curriculum for families. You are given the pedagogical framework, the profile template, and one complete exemplar figure (every file). You will write the same set of files for a new figure.

Standards:
- Follow the exemplar's structure, headings, proportions and voice exactly; the markdown must parse with the same tools.
- Accuracy over flourish. Draw on primary sources and the standard scholarly biographies; name them. Where the record is uncertain or legendary, say so in the text and mark the sentence with [uncertain]. Never invent quotations, dates, or anecdotes.
- Teach virtue and risk in the same breath. Every figure has both.
- Age calibration is real: the 8-10 lesson protects the child from what the parent guide says to leave for later; the 15-18 lesson protects nothing and judges everything.
- Output only the markdown for the requested file. No preface, no commentary, no code fences.`;

const EXEMPLAR_FILES = ["README.md", "student-ages-8-10.md", "student-ages-11-14.md", "student-ages-15-18.md", "parent-guide.md", "one-week-lesson.md"];

function referencePrefix(root: string, exemplar: string): Anthropic.Beta.Messages.BetaTextBlockParam[] {
  const blocks: Anthropic.Beta.Messages.BetaTextBlockParam[] = [{ type: "text", text: SYSTEM_INTRO }];
  blocks.push({ type: "text", text: `# framework/GREAT_MAN_FRAMEWORK.md\n\n${readCorpusFile("framework/GREAT_MAN_FRAMEWORK.md", root)}` });
  blocks.push({ type: "text", text: `# framework/PROFILE_TEMPLATE.md\n\n${readCorpusFile("framework/PROFILE_TEMPLATE.md", root)}` });
  blocks.push({ type: "text", text: `# research/${exemplar}-full.md (exemplar research essay)\n\n${readCorpusFile(`research/${exemplar}-full.md`, root)}` });
  for (const f of EXEMPLAR_FILES) {
    blocks.push({ type: "text", text: `# profiles/${exemplar}/${f} (exemplar)\n\n${readCorpusFile(`profiles/${exemplar}/${f}`, root)}` });
  }
  blocks[blocks.length - 1]!.cache_control = { type: "ephemeral" };
  return blocks;
}

const DRAFT_FOOTER = (name: string, model: string) =>
  `\n\n---\n\n*Draft generated with ${model} for Nova Schola. Review Status: Draft — verify every claim against the sources before use.*\n*Figure: ${name}*\n`;

export async function generateProfile(opts: GenerateOptions): Promise<GenerateResult> {
  const root = opts.root ?? REPO_ROOT;
  const client = opts.client ?? new Anthropic();
  const spec = resolveModel(opts.model);
  const exemplar = opts.exemplar ?? "alexander";
  const usage = emptyUsage();
  const drafts: Record<string, string> = {};
  const files: string[] = [];

  if (opts.web && !/claude-(opus|sonnet)-5-5/.test(spec.id)) {
    throw new Error(`--web uses the web_search_20260209 server tool, which needs the tutor (Opus 5.5) or fast (Sonnet 5.5) tier, not ${spec.id}.`);
  }
  if (!opts.dryRun && existsSync(join(root, "profiles", opts.slug))) {
    throw new Error(`profiles/${opts.slug} already exists; choose another slug or remove it first.`);
  }

  const system = referencePrefix(root, exemplar);
  const subject = [
    `Figure: ${opts.name} (slug: ${opts.slug})`,
    `Era group: ${opts.eraGroup}; sequence day ${opts.day}`,
    opts.era ? `Era line: ${opts.era}` : undefined,
    opts.domain ? `Domain: ${opts.domain}` : undefined,
    opts.notes ? `Author notes: ${opts.notes}` : undefined,
  ]
    .filter(Boolean)
    .join("\n");

  const run = async (userText: string, label: string, tools?: Anthropic.Beta.Messages.BetaToolUnion[]): Promise<string> => {
    opts.onStage?.(label);
    const messages: Anthropic.Beta.Messages.BetaMessageParam[] = [{ role: "user", content: userText }];
    let text = "";
    for (;;) {
      const stream = client.beta.messages.stream({
        model: spec.id,
        max_tokens: 32000,
        system,
        messages,
        thinking: { type: "adaptive" },
        output_config: { effort: opts.effort ?? "high" },
        ...(tools ? { tools } : {}),
        ...(spec.serverFallback ? { betas: [FALLBACK_BETA], fallbacks: "default" as const } : {}),
      });
      stream.on("text", (d) => opts.onText?.(d));
      const message = await stream.finalMessage();
      addUsage(usage, message.usage);
      messages.push({ role: "assistant", content: message.content });
      text += message.content.filter((b): b is Anthropic.Beta.Messages.BetaTextBlock => b.type === "text").map((b) => b.text).join("");
      if (message.stop_reason === "pause_turn") continue; // server tool hit its iteration limit; resume
      if (message.stop_reason === "refusal") throw new Error(`The model declined while writing ${label}.`);
      if (message.stop_reason === "max_tokens") throw new Error(`Output truncated while writing ${label}; raise max_tokens or split the task.`);
      break;
    }
    return text.trim() + "\n";
  };

  // 1. Research essay
  const webTools: Anthropic.Beta.Messages.BetaToolUnion[] | undefined = opts.web
    ? [{ type: "web_search_20260209", name: "web_search", max_uses: 10 }]
    : undefined;
  const research = await run(
    `${subject}\n\nWrite research/${opts.slug}-full.md: the full research essay, following framework/PROFILE_TEMPLATE.md exactly as the exemplar research essay does (metadata table, essential question, life overview by phase, defining moments, failures and recovery, teaching wisdom, primary sources, cross-references, the "For the AI Tutor" section with misconceptions, bibliography, timeline).${opts.web ? " Use web search to verify dates, quotations and sources before you commit to them." : ""}`,
    `research/${opts.slug}-full.md`,
    webTools,
  );
  drafts[`research/${opts.slug}-full.md`] = research + DRAFT_FOOTER(opts.name, spec.label);

  // 2. The six profile files, each grounded in the essay just written
  for (const { file, brief } of PROFILE_FILES) {
    const text = await run(
      `${subject}\n\nHere is the research essay for ${opts.name}, written a moment ago. Treat it as the record:\n\n<research_essay>\n${research}\n</research_essay>\n\nWrite profiles/${opts.slug}/${file}: ${brief}. Mirror profiles/${exemplar}/${file} in structure, headings, length and voice, adapted faithfully to ${opts.name}. Link the other files with the same relative paths the exemplar uses.`,
      `profiles/${opts.slug}/${file}`,
    );
    drafts[`profiles/${opts.slug}/${file}`] = text + DRAFT_FOOTER(opts.name, spec.label);
  }
  drafts[`profiles/${opts.slug}/meta.json`] = JSON.stringify({ name: opts.name, eraGroup: opts.eraGroup, day: opts.day, generatedBy: spec.id, status: "draft" }, null, 2) + "\n";

  if (!opts.dryRun) {
    mkdirSync(join(root, "profiles", opts.slug), { recursive: true });
    mkdirSync(join(root, "research"), { recursive: true });
    for (const [rel, content] of Object.entries(drafts)) {
      writeFileSync(join(root, rel), content);
      files.push(rel);
    }
  }
  return { files, drafts, usage, estimatedCostUsd: estimateCost(usage, spec) };
}

export type { AgeRange };
